	}
}

async function caches(ordinary: string[] = [], replies: string[] = []) {
	await timeline.del(key(), key(true));
	if (ordinary.length) {
		await timeline.rpush(key(), ...ordinary);
	}
	if (replies.length) {
		await timeline.rpush(key(true), ...replies);
	}
}

