	if (count) {
		expect(result.prev).toBe(`https://local.example/users/alice/outbox?page=true&since_id=${id(count)}`);
		expect(result.next).toBe(`https://local.example/users/alice/outbox?page=true&until_id=${id(Math.max(1, count - 19))}`);
	} else {
